from flask import Flask, request, jsonify
import pyautogui
import base64
import io
import time

app = Flask(__name__)

# Create a dictionary to store the screen sharing sessions
sessions = {}

@app.route('/start_session', methods=['POST'])
def start_session():
    url = request.json['url']
    if url not in sessions:
        sessions[url] = {'start_time': time.time(), 'active': True, 'screen_data': b''}
        return {'link': f'http://localhost:5000/{url}'}
    else:
        return {'error': 'A screen sharing session is already active for this URL.'}, 400

@app.route('/get_screen', methods=['GET'])
def get_screen():
    url = request.args.get('url')
    if url in sessions:
        current_time = time.time()
        session = sessions[url]
        if session['active']:
            if current_time - session['start_time'] < 60: # Allow the session to last for 1 minute
                try:
                    img = pyautogui.screenshot()
                    buf = io.BytesIO()
                    img.save(buf, format='PNG')
                    buf.seek(0)
                    screen_data = buf.read()
                    session['screen_data'] += screen_data
                    return {'image': base64.b64encode(screen_data).decode('utf-8')}
                except:
                    return {'error': 'Failed to capture the screen.'}, 500
            else:
                return {'error': 'Screen sharing session has expired.'}, 400
        else:
            return {'error': 'Screen sharing session is not active.'}, 400
    else:
        return {'error': 'No screen sharing session found for this URL.'}, 404

@app.route('/stop_session', methods=['POST'])
def stop_session():
    url = request.json['url']
    if url in sessions:
        sessions[url]['active'] = False
        return {'message': 'Screen sharing session has been stopped.'}
    else:
        return {'error': 'No screen sharing session found for this URL.'}, 404

if __name__ == '__main__':
