import { createContext, useState } from 'react';

const FeedbackContext = createContext();

const FeedbackProvider = ({ children }) => {
  const [feedbackForm, setFeedbackForm] = useState({
    questions: [
      { id: 1, text: 'How was the course material?' },
      { id: 2, text: 'How was the instructor?' },
      { id: 3, text: 'How was the pacing of the course?' },
    ],
    answers: [],
  });

  const handleAnswerChange = (questionId, answer) => {
    setFeedbackForm((prevFeedbackForm) => {
      const newAnswers = [...prevFeedbackForm.answers];
      newAnswers[questionId - 1] = answer;
      return { ...prevFeedbackForm, answers: newAnswers };
    });
  };

  return (
    <FeedbackContext.Provider value={{ feedbackForm, handleAnswerChange }}>
      {children}
    </FeedbackContext.Provider>
  );
};

export { FeedbackContext, FeedbackProvider };
```
