#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  gpioInitialise();

  // Set GPIO pin 12 as an output
  gpioSetup(12, PI_OUTPUT);

  // Set the initial state of the pin to LOW (0)
  gpioWrite(12, 0);

  // Loop indefinitely and toggle the pin on each iteration
  while (1) {
    gpioWrite(12, 1);  // Set the pin HIGH (1)
    delay(1000);       // Wait for 1 second
    gpioWrite(12, 0);  // Set the pin LOW (0)
    delay(1000);       // Wait for 1 second
  }

  // Clean up and exit
  gpioTerminate();
  return 0;
}
